"""Verificación de interfaz con Playwright (equivalente a las pruebas Selenium). Uso: python3 tests/ui_check_playwright.py <url> <carpeta_capturas>"""
import sys, json, os
from playwright.sync_api import sync_playwright
base, out = sys.argv[1], sys.argv[2]
os.makedirs(out, exist_ok=True)
res = []
def ok(n, c): res.append((n, bool(c))); print(('OK    ' if c else 'FALLA ') + n)
with sync_playwright() as p:
    b = p.chromium.launch(); ctx = b.new_context(viewport={'width': 1280, 'height': 800}, accept_downloads=True, bypass_csp=True); pg = ctx.new_page(); errs = []
    pg.on('dialog', lambda d: d.accept()); pg.on('pageerror', lambda e: errs.append(str(e))); pg.route('**/fonts.googleapis.com/**', lambda r: r.abort())
    T = lambda i: f'[data-testid={i}]'
    def shot(n, full=False):
        pg.evaluate("document.getElementById('toast').hidden=true"); pg.screenshot(path=out + '/' + n, full_page=full)
    def pdf_abierto(boton):
        pg.evaluate('window.__o=[];window.open=u=>{window.__o.push(u)}'); pg.click(T(boton)); pg.wait_for_function("window.__o.some(u=>u&&u.startsWith('blob:'))")
        return pg.evaluate("fetch(window.__o.filter(u=>u&&u.startsWith('blob:')).pop()).then(r=>r.arrayBuffer()).then(b=>new TextDecoder().decode(b.slice(0,4)))") == '%PDF'
    pg.goto(base); pg.fill(T('login-usuario'), 'admin'); pg.fill(T('password'), 'mala'); pg.click(T('login-submit')); pg.wait_for_function("document.querySelector('[data-testid=login-error]').textContent!==''")
    ok('CP01 Login con credenciales inválidas muestra error', pg.inner_text(T('login-error')) == 'Credenciales no válidas'); shot('ui_login.png', False)
    pg.fill(T('login-usuario'), 'admin'); pg.fill(T('password'), 'Tablero2026*'); pg.click(T('login-submit')); pg.wait_for_selector(T('tab-cobrar'))
    ok('CP02 Login válido muestra la sesión del Administrador', 'Administrador' in pg.inner_text(T('usuario')))
    pg.click(T('tab-productos')); pg.wait_for_selector(T('tabla') + ' tr')
    ok('CP03 Consultar: lista de productos cargada', pg.locator(T('tabla') + ' tr').count() >= 7)
    ok('CP04 Alerta de stock bajo visible (Papas, Agua)', 'Papas' in pg.inner_text(T('alerta-stock'))); shot('ui_listar.png', False)
    pg.click(T('nuevo')); pg.fill('#f_nombre', 'Hamburguesa'); pg.fill('#f_precio_venta', '12000'); pg.fill('#f_costo', '6000'); pg.fill('#f_stock_actual', '10'); pg.fill('#f_stock_minimo', '4')
    shot('ui_crear.png', False); pg.click(T('guardar')); pg.wait_for_timeout(500)
    ok('CP05 Insertar: el producto nuevo aparece en la tabla', 'Hamburguesa' in pg.inner_text(T('tabla')))
    pg.fill(T('buscar'), 'Hambur'); pg.wait_for_timeout(600)
    ok('CP06 Consultar con búsqueda filtra los resultados', pg.locator(T('tabla') + ' tr').count() == 1)
    pg.click(T('editar')); pg.fill('#f_precio_venta', '13500'); shot('ui_editar.png', False); pg.click(T('guardar')); pg.wait_for_timeout(500)
    ok('CP07 Actualizar: el precio nuevo se muestra', '13500' in pg.inner_text(T('tabla')))
    pg.click(T('eliminar')); pg.wait_for_timeout(500)
    ok('CP08 Eliminar: el producto ya no aparece', 'Hamburguesa' not in pg.inner_text(T('tabla')))
    pg.click(T('tab-categorias')); pg.wait_for_selector(T('tabla') + ' tr'); pg.click(T('eliminar')); pg.wait_for_timeout(500)
    ok('CP09 Integridad: no deja eliminar una categoría con productos', 'relacionados' in pg.inner_text('#toast'))
    # Cobrar: ejemplo del documento de requerimientos (cancha + mesa + 2 gaseosas + pizza = $88.000)
    pg.click(T('tab-cobrar')); pg.wait_for_selector(T('agregar')); pg.fill(T('cliente'), 'Juan Pérez')
    pg.select_option(T('tipo-item'), 'cancha'); pg.click(T('agregar'))
    pg.select_option(T('tipo-item'), 'mesa'); pg.fill(T('descripcion'), 'Mesa 3'); pg.fill(T('valor'), '10000'); pg.click(T('agregar'))
    opt = lambda n: pg.eval_on_selector(T('producto'), 's=>[...s.options].find(o=>o.text.startsWith("%s")).value' % n)
    pg.select_option(T('tipo-item'), 'consumo'); pg.select_option(T('producto'), opt('Gaseosa')); pg.fill(T('cantidad'), '2'); pg.click(T('agregar'))
    pg.select_option(T('producto'), opt('Pizza')); pg.fill(T('cantidad'), '1'); pg.click(T('agregar'))
    pg.select_option(T('metodo'), 'Transferencia'); pg.wait_for_function("document.querySelector('[data-testid=qr]') && document.querySelector('[data-testid=qr]').src.startsWith('data:image/png')")
    try: pg.wait_for_function("document.querySelector('[data-testid=total]').textContent.includes('88.000')", timeout=5000)
    except Exception: print('DEPURAR items:', pg.inner_text(T('items')).replace('\n', ' | '), '| total:', pg.inner_text(T('total')))
    ok('CP10 Cobrar: el total del ejemplo es $ 88.000', '88.000' in pg.inner_text(T('total')))
    ok('CP11 Pago por transferencia muestra el código QR', pg.get_attribute(T('qr'), 'src').startswith('data:image/png'))
    shot('ui_cobrar.png', True); pg.click(T('generar')); pg.wait_for_selector(T('resultado'))
    ok('CP12 Se genera el comprobante con su número', 'Comprobante No. 000001' in pg.inner_text(T('resultado'))); shot('ui_cobrar_resultado.png', True)
    ok('CP13 La tirilla se genera como PDF válido', pdf_abierto('ver-tirilla'))
    pg.click(T('tab-rapida')); pg.fill(T('r-nombre'), 'Juan Pérez'); pg.fill(T('r-celular'), '3001234567'); pg.select_option('#rm', 'Transferencia'); shot('ui_rapida_form.png', True); pg.click(T('r-generar')); pg.wait_for_selector(T('r-mensaje'))
    ok('CP14 Reserva rápida: mensaje de WhatsApp con los datos de la reserva', 'tu reserva está confirmada' in pg.inner_text(T('r-mensaje')) and 'Transferencia' in pg.inner_text(T('r-mensaje')))
    ok('CP15 El envío queda en estado simulado sin credenciales', 'simulado' in pg.inner_text(T('r-estado'))); shot('ui_rapida.png', True)
    pg.click(T('tab-comprobantes')); pg.wait_for_selector(T('lista-comprobantes') + ' tr')
    ok('CP16 La lista de comprobantes muestra los generados', pg.locator(T('lista-comprobantes') + ' tr').count() >= 2); shot('ui_comprobantes.png', True)
    pg.click(T('tab-reportes')); pg.wait_for_selector(T('kpis'))
    ok('CP17 Reporte diario con las ventas del día (suma de los comprobantes)', '138.000' in pg.inner_text(T('kpis'))); shot('ui_reportes.png', True)
    with pg.expect_download() as d: pg.click(T('reporte-excel'))
    ok('CP18 El reporte se exporta a Excel', d.value.suggested_filename.endswith('.xlsx'))
    ok('CP19 El reporte se genera como PDF válido', pdf_abierto('reporte-pdf'))
    pg.select_option(T('periodo'), 'mensual'); pg.click(T('ver-reporte')); pg.wait_for_timeout(500)
    ok('CP20 Reporte mensual disponible para el Administrador', '138.000' in pg.inner_text(T('kpis')))
    pg.click(T('tab-clientes')); pg.wait_for_selector(T('tabla') + ' tr'); pg.locator(T('historial')).first.click(); pg.wait_for_timeout(500)
    ok('CP21 Historial del cliente con visitas y fidelización', 'Visitas' in pg.inner_text('#mf') and 'reserva' in pg.inner_text('#mf')); shot('ui_historial.png', False); pg.click('#cancel')
    pg.click(T('tab-auditoria')); pg.wait_for_selector(T('lista-auditoria') + ' tr')
    ok('CP22 Auditoría muestra usuario, acción y fecha', 'LOGIN' in pg.inner_text(T('lista-auditoria')) and 'comprobantes' in pg.inner_text(T('lista-auditoria'))); shot('ui_auditoria.png', True)
    pg.click(T('tab-negocio')); pg.wait_for_selector(T('lic-estado')); pg.fill(T('n-nombre'), 'Complejo Deportivo "El Golazo"'); pg.click(T('n-guardar')); pg.wait_for_timeout(500)
    ok('CP23 Se guardan los datos del negocio', 'guardados' in pg.inner_text('#toast')); ok('CP24 La licencia aparece sin activar', 'Sin activar' in pg.inner_text(T('lic-estado')))
    pg.fill(T('n-nombre'), 'Cancha Sintética Fútbol 10'); pg.click(T('n-guardar')); pg.wait_for_timeout(300); shot('ui_negocio.png', True)
    # ---- Dashboard, mesas y tema (CP28 en adelante) ----
    pg.click(T('tab-inicio')); pg.wait_for_selector(T('inicio-kpis'))
    ok('CP28 El dashboard Inicio muestra los indicadores del día', 'Ventas de hoy' in pg.inner_text(T('inicio-kpis')) and 'Mesas ocupadas' in pg.inner_text(T('inicio-kpis'))); shot('ui_inicio.png', True)
    pg.click(T('tab-mesas')); pg.wait_for_selector(T('tablero'))
    color = lambda sel, prop: pg.eval_on_selector(sel, '(e,p)=>getComputedStyle(e)[p]', prop)
    ok('CP29 Tablero de mesas: las 5 mesas libres en verde', pg.locator('.mesa.libre').count() == 5 and color(T('mesa-1'), 'borderLeftColor') == 'rgb(46, 125, 79)')
    pg.click(T('mesa-abrir-1')); pg.select_option(T('ocupar-cliente'), label='Los Halcones'); pg.click(T('ocupar-confirmar')); pg.wait_for_selector(T('consumos-total'))
    ok('CP30 Mesa ocupada: el detalle de consumos se abre y la mesa pasa a naranja', 'Ocupada' in pg.inner_text('#mf') and color(T('mesa-1'), 'borderLeftColor') == 'rgb(241, 90, 36)')
    opt = lambda n: pg.eval_on_selector(T('consumo-producto'), 's=>[...s.options].find(o=>o.text.startsWith("%s")).value' % n)
    pg.select_option(T('consumo-producto'), opt('Gaseosa')); pg.fill(T('consumo-cantidad'), '2'); pg.click(T('consumo-agregar')); pg.wait_for_function("document.querySelector('[data-testid=consumos-total]').textContent.includes('8.000')")
    pg.select_option(T('consumo-producto'), opt('Pizza')); pg.fill(T('consumo-cantidad'), '1'); pg.click(T('consumo-agregar')); pg.wait_for_function("document.querySelector('[data-testid=consumos-total]').textContent.includes('28.000')")
    ok('CP31 Los consumos se acumulan en la mesa ($ 28.000)', '28.000' in pg.inner_text(T('consumos-total')))
    pg.select_option(T('consumo-producto'), opt('Empanada')); pg.fill(T('consumo-cantidad'), '1'); pg.select_option(T('consumo-cliente'), label='Amigos del barrio'); pg.click(T('consumo-agregar')); pg.wait_for_function("document.querySelector('[data-testid=consumos-total]').textContent.includes('31.500')")
    ok('CP32 Un consumo se vincula a otro cliente y se detalla por cliente', 'Amigos del barrio' in pg.inner_text(T('consumos-tabla')) and 'Los Halcones' in pg.inner_text('#mf')); shot('ui_mesa_detalle.png')
    ok('CP33 Con consumos no se puede marcar libre (botón deshabilitado)', pg.is_disabled(T('mesa-liberar')))
    pg.click(T('mesa-cerrar')); pg.select_option(T('cerrar-metodo'), 'Transferencia'); pg.wait_for_function("document.querySelector('[data-testid=qr]') && document.querySelector('[data-testid=qr]').src.startsWith('data:image/png')")
    pg.click(T('cerrar-confirmar')); pg.wait_for_selector(T('cierre-resultado'))
    ok('CP34 Cierre de mesa: comprobante generado y tirilla en PDF', 'Comprobante No.' in pg.inner_text(T('cierre-resultado')) and '31.500' in pg.inner_text(T('cierre-resultado')) and pdf_abierto('ver-tirilla'))
    pg.click('#mf [data-close]'); pg.wait_for_function("document.querySelector('[data-testid=mesa-estado-1]').textContent.includes('Libre')")
    ok('CP35 La mesa vuelve a quedar libre (verde)', color(T('mesa-1'), 'borderLeftColor') == 'rgb(46, 125, 79)')
    pg.click(T('mesa-nueva')); pg.fill(T('mesa-numero'), '9'); pg.click(T('mesa-guardar')); pg.wait_for_selector(T('mesa-9'))
    pg.click(T('mesa-eliminar-9')); pg.wait_for_function("!document.querySelector('[data-testid=mesa-9]')")
    ok('CP36 El Administrador crea y elimina mesas', True)
    pg.click(T('tab-productos')); pg.wait_for_selector(T('tabla') + ' tr'); pg.click(T('nuevo')); pg.click(T('guardar')); pg.wait_for_selector(T('form-error'), state='visible')
    ok('CP37 Validación corporativa: mensaje con ícono y campo resaltado', 'Revise el campo «Nombre»' in pg.inner_text(T('form-error')) and 'invalid' in (pg.get_attribute('#f_nombre', 'class') or '') and pg.locator(T('form-error') + ' svg').count() == 1); pg.wait_for_timeout(450); shot('ui_validacion.png'); pg.click('#mf [data-close]')
    nav = pg.eval_on_selector('.side', 'e=>{const r=e.getBoundingClientRect();return [r.left,r.width,r.top]}')
    ok('CP38 Escritorio: barra lateral fija con el logo y menús con ícono', nav[0] == 0 and nav[1] >= 240 and pg.locator('.side .brand').is_visible() and pg.locator('.tab svg').count() >= 13)
    ok('CP39 Botones con animación suave (transición definida)', pg.eval_on_selector(T('nuevo'), 'e=>getComputedStyle(e).transitionDuration') not in ('0s', ''))
    pg.click(T('tab-usuarios')); pg.wait_for_selector(T('tabla') + ' tr'); pg.click(T('nuevo')); pg.fill('#f_nombre', 'Prueba UI'); pg.fill('#f_usuario', 'prueba.ui'); pg.select_option('#f_id_rol', '2'); pg.fill('#f_password', 'ClaveSegura1'); pg.click(T('guardar'))
    pg.wait_for_function("document.querySelector('[data-testid=tabla]').textContent.includes('prueba.ui')")
    ok('CP43 Administrador crea un usuario con nombre de usuario (correo opcional)', 'Prueba UI' in pg.inner_text(T('tabla')))
    fila = pg.locator(T('tabla') + ' tr', has_text='prueba.ui'); fila.locator(T('editar')).click(); pg.wait_for_selector(T('guardar')); pg.fill('#f_nombre', 'Prueba Editada'); pg.click(T('guardar'))
    pg.wait_for_function("document.querySelector('[data-testid=tabla]').textContent.includes('Prueba Editada')")
    ok('CP44 Administrador edita el usuario', 'Prueba Editada' in pg.inner_text(T('tabla')))
    pg.locator(T('tabla') + ' tr', has_text='prueba.ui').locator(T('eliminar')).click()
    pg.wait_for_function("!document.querySelector('[data-testid=tabla]').textContent.includes('prueba.ui')")
    ok('CP45 Administrador elimina un usuario sin historial', 'prueba.ui' not in pg.inner_text(T('tabla')))
    pg.click(T('logout')); pg.fill(T('login-usuario'), 'operador'); pg.fill(T('password'), 'Tablero2026*'); pg.click(T('login-submit')); pg.wait_for_selector(T('tab-cobrar'))
    ok('CP25 El Operador ve Cobrar pero no Auditoría ni Negocio', pg.locator(T('tab-auditoria')).count() == 0 and pg.locator(T('tab-negocio')).count() == 0 and pg.locator(T('tab-usuarios')).count() == 0)
    pg.click(T('tab-reportes')); pg.wait_for_selector(T('kpis')); ok('CP26 El Operador solo tiene el reporte diario', pg.locator(T('periodo') + ' option').count() == 1)
    pg.click(T('tab-mesas')); pg.wait_for_selector(T('tablero'))
    ok('CP40 Operador: no ve Nueva mesa ni Eliminar, pero sí puede ocupar y registrar consumos', pg.locator(T('mesa-nueva')).count() == 0 and pg.locator('[data-testid^=mesa-eliminar]').count() == 0)
    pg.click(T('mesa-abrir-2')); pg.click(T('ocupar-confirmar')); pg.wait_for_selector(T('consumos-total')); pg.select_option(T('consumo-producto'), opt('Cerveza')); pg.click(T('consumo-agregar')); pg.wait_for_function("document.querySelector('[data-testid=consumos-total]').textContent.includes('5.000')")
    ok('CP41 Operador: ocupa la mesa 2 y registra un consumo de $ 5.000', '5.000' in pg.inner_text(T('consumos-total')) and pg.is_disabled(T('mesa-liberar'))); pg.click('#mf #cancel'); pg.wait_for_selector(T('mesa-estado-2'))
    shot('ui_mesas.png', True)
    pg.set_viewport_size({'width': 390, 'height': 844}); pg.wait_for_timeout(300)
    nb = pg.eval_on_selector('.side', 'e=>{const r=e.getBoundingClientRect();return [r.bottom,r.width,innerHeight,innerWidth]}')
    ok('CP42 Móvil: navegación inferior a todo el ancho', abs(nb[0] - nb[2]) < 2 and nb[1] == nb[3] and not pg.locator('.side .brand').is_visible()); shot('ui_mesas_movil.png')
    pg.click(T('tab-cobrar')); pg.wait_for_selector(T('agregar')); shot('ui_movil.png')
    ok('CP27 Sin errores de JavaScript en la consola', not errs)
    b.close()
json.dump(res, open(out + '/ui_results.json', 'w'))
print(sum(1 for _, c in res if c), 'de', len(res))
